// --- AI HELPERS ---

async function callAIWithFallback(systemPrompt, userPrompt, opts = {}) {
  const providers = [
    {
      name: 'gemini',
      url: '/api/ai/gemini-compat',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: {
        model: 'gemini-3.1-pro-preview',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        temperature: opts.temperature ?? 0.3,
        max_tokens: opts.maxTokens ?? 1200,
      },
      extract: (data) => data?.choices?.[0]?.message?.content,
    },
    {
      name: 'anthropic',
      url: '/api/ai/anthropic',
      headers: { 'Content-Type': 'application/json' },
      body: {
        model: 'claude-opus-4-6',
        max_tokens: opts.maxTokens ?? 1200,
        system: systemPrompt,
        messages: [{ role: 'user', content: userPrompt }],
      },
      extract: (data) => data?.content?.[0]?.text,
    },
    {
      name: 'openai',
      url: '/api/ai/openai',
      headers: { 'Content-Type': 'application/json', 'x-openai-endpoint': 'chat' },
      body: {
        model: 'gpt-5.5',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: userPrompt },
        ],
        temperature: opts.temperature ?? 0.3,
      },
      extract: (data) => data?.choices?.[0]?.message?.content,
    },
  ];

  let lastErr = null;
  for (const p of providers) {
    try {
      const res = await fetch(p.url, { method: 'POST', headers: p.headers, body: JSON.stringify(p.body) });
      if (!res.ok) { lastErr = new Error(`${p.name} HTTP ${res.status}`); continue; }
      const data = await res.json();
      const text = p.extract(data);
      if (!text || typeof text !== 'string') { lastErr = new Error(`${p.name} returned empty`); continue; }
      return { text, provider: p.name };
    } catch (e) { lastErr = e; }
  }
  console.warn(`All AI providers failed. Last error: ${lastErr?.message || 'unknown'}`);
  return { text: opts.fallbackText || "Synthesis failed.", provider: 'fallback' };
}

const VS_INSTRUCTION = `
Before answering, generate FIVE distinct candidate responses with diverse framings (different metaphors, different emotional registers, different rhetorical structures). Assign each a probability mass reflecting how likely a typical model would emit it. Then return the candidate with the LOWEST probability that still earns >=7/10 on quality and grounded relevance — the tail concept, not the modal one. Output ONLY the final chosen candidate in the requested format. Do not show the intermediate candidates.
`.trim();

async function callAIWithVS(systemPrompt, userPrompt, opts = {}) {
  return callAIWithFallback(
    `${systemPrompt}\n\n${VS_INSTRUCTION}`,
    userPrompt,
    { ...opts, temperature: opts.temperature ?? 0.85 }
  );
}

// --- SHARED UI COMPONENTS ---

const Button = ({ children, variant = 'primary', onClick, disabled, loading, className = '', icon: Icon }) => {
  const baseStyle = "relative inline-flex items-center justify-center px-4 h-[44px] rounded-[2px] font-body font-semibold text-[14px] transition-all duration-200 focus:outline-none focus-visible:ring-2 focus-visible:ring-offset-2 focus-visible:ring-nu-red disabled:opacity-50 disabled:cursor-not-allowed";
  const variants = {
    primary: "bg-nu-red text-white hover:bg-nu-red-deep active:scale-[0.98]",
    secondary: "bg-surface text-text-primary border border-border hover:bg-panel active:scale-[0.98]",
    ghost: "bg-transparent text-text-secondary hover:bg-surface hover:text-text-primary active:scale-[0.98]",
    teams: "bg-[#5B5FC7] text-white hover:bg-[#464EB8] active:scale-[0.98]"
  };

  return (
    <button 
      className={`${baseStyle} ${variants[variant]} ${className}`}
      onClick={onClick}
      disabled={disabled || loading}
    >
      {loading ? (
        <motion.div 
          className="absolute inset-0 overflow-hidden rounded-[2px]"
          initial={{ opacity: 0 }} animate={{ opacity: 1 }}
        >
          <div className="w-full h-full bg-gradient-to-r from-transparent via-white/20 to-transparent animate-[shimmer_1.5s_infinite] -translate-x-full" />
        </motion.div>
      ) : null}
      <span className={`flex items-center gap-2 ${loading ? 'opacity-0' : 'opacity-100'}`}>
        {Icon && <Icon size={16} />}
        {children}
      </span>
    </button>
  );
};

const Badge = ({ children, variant = 'neutral', className = '' }) => {
  const baseStyle = "inline-flex items-center px-2 py-0.5 rounded-[2px] font-body font-semibold text-[12px] tracking-wide uppercase";
  const variants = {
    probability: "bg-surface border border-border text-text-secondary",
    ferpa: "bg-nu-red-tint text-nu-red border border-nu-red/20",
    neutral: "bg-panel text-text-tertiary"
  };
  return <span className={`${baseStyle} ${variants[variant]} ${className}`}>{children}</span>;
};

const Skeleton = ({ className = '' }) => (
  <div className={`relative overflow-hidden bg-surface rounded-[2px] ${className}`}>
    <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/40 to-transparent animate-[shimmer_1.5s_infinite] -translate-x-full" />
  </div>
);

const TypewriterText = ({ text, speed = 60, className = '' }) => {
  const words = text.split(' ');
  return (
    <p className={className}>
      {words.map((word, i) => (
        <motion.span
          key={i}
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          transition={{ duration: 0.2, delay: i * (speed / 1000) }}
        >
          {word}{' '}
        </motion.span>
      ))}
    </p>
  );
};

// --- SCREENS ---

const ScreenSearch = ({ onNavigate, setQuery, query, savedCount }) => {
  const [greeting, setGreeting] = useState('');
  const [isFocused, setIsFocused] = useState(false);
  const [placeholderIdx, setPlaceholderIdx] = useState(0);
  const placeholders = ["show me someone who started undeclared...", "biology to climate policy...", "business to film..."];

  useEffect(() => {
    let interval;
    if (!isFocused) {
      interval = setInterval(() => {
        setPlaceholderIdx(p => (p + 1) % placeholders.length);
      }, 4000);
    }
    return () => clearInterval(interval);
  }, [isFocused]);

  useEffect(() => {
    const fetchGreeting = async () => {
      const res = await callAIWithFallback(
        "You are a longitudinal companion analyzing a student's past queries. Keep the greeting under 15 words.",
        "Student context: Aisha, undeclared. Past queries: product design. Generate a short greeting.",
        { fallbackText: '{"greeting": "Welcome back. What trajectory would you like to explore today?"}' }
      );
      try {
        const parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
        setGreeting(parsed.greeting || "Welcome back.");
      } catch (e) { setGreeting("Welcome back."); }
    };
    fetchGreeting();
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (query.trim()) onNavigate('screen_results');
  };

  return (
    <motion.div 
      className="flex flex-col h-full p-6"
      initial={{ x: 20, opacity: 0 }} animate={{ x: 0, opacity: 1 }} transition={{ duration: 0.28, ease: "easeOut" }}
    >
      <div className="flex-1 flex flex-col justify-center max-w-2xl mx-auto w-full space-y-8">
        <div className="space-y-2">
          <h1 className="font-display text-[32px] font-bold text-text-primary tracking-tight">Trailblazer Time Machine</h1>
          <p className="font-body text-[16px] text-text-secondary h-6">
            {greeting ? <TypewriterText text={greeting} speed={30} /> : <Skeleton className="h-5 w-3/4" />}
          </p>
        </div>

        <form onSubmit={handleSubmit} className="relative">
          <div className={`flex items-center bg-white border ${isFocused ? 'border-nu-red ring-1 ring-nu-red' : 'border-border'} rounded-[4px] shadow-sm transition-all duration-200 p-2`}>
            <lucide.Search className="text-text-tertiary ml-2" size={20} />
            <input
              type="text"
              className="flex-1 bg-transparent border-none focus:ring-0 font-body text-[16px] px-4 py-2 outline-none"
              placeholder={placeholders[placeholderIdx]}
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              onFocus={() => setIsFocused(true)}
              onBlur={() => setIsFocused(false)}
            />
            <Button type="submit" variant="primary" className="h-[36px] px-4 rounded-[2px]">Explore</Button>
          </div>
        </form>

        <div className="space-y-3">
          <p className="font-label text-[14px] text-text-tertiary uppercase tracking-wider">Suggested Explorations</p>
          <div className="flex flex-wrap gap-2">
            {['undeclared → product design', 'biology → climate policy', 'business → film'].map(chip => (
              <button 
                key={chip}
                onClick={() => { setQuery(chip); onNavigate('screen_results'); }}
                className="px-3 py-1.5 bg-surface border border-border rounded-[2px] font-body text-[14px] text-text-secondary hover:border-nu-red hover:text-nu-red transition-colors"
              >
                {chip}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="mt-auto pt-6 border-t border-border flex justify-between items-center">
        <div className="flex items-center gap-2 text-text-tertiary font-body text-[13px]">
          <lucide.Bookmark size={14} />
          <span>Your Co-op Compass has {savedCount} saved trajectories</span>
        </div>
        <Badge variant="ferpa" className="flex items-center gap-1">
          <lucide.Shield size={12} /> FERPA k≥5 Guard Active
        </Badge>
      </div>
    </motion.div>
  );
};

const ScreenResults = ({ query, onNavigate, setSelectedArcId, onSaveArc }) => {
  const [isLoading, setIsLoading] = useState(true);
  const [arcs, setArcs] = useState([]);
  const [ferpaStatus, setFerpaStatus] = useState('pending');

  useEffect(() => {
    const fetchResults = async () => {
      setIsLoading(true);

      const retRes = await callAIWithFallback(
        "You parse natural language career queries into structured filters and retrieve matching anonymized trajectory records. Output JSON.",
        `Query: '${query}'. Return top matching trajectory IDs.`,
        { fallbackText: '{"matched_trajectory_ids": ["TRJ-0114", "TRJ-0156", "TRJ-0241"]}' }
      );
      let matchedIds = ["TRJ-0114", "TRJ-0156", "TRJ-0241"];
      try { matchedIds = JSON.parse(retRes.text.replace(/```json|```/g, '')).matched_trajectory_ids || matchedIds; } catch(e){}

      const ferpaRes = await callAIWithFallback(
        "You check cohort size. If query is narrow, return aggregate_only. Output JSON.",
        `Query: ${query}. Cohort size: 12.`,
        { fallbackText: '{"status": "passthrough", "cohort_size": 12}' }
      );

      let status = 'passthrough';
      try { status = JSON.parse(ferpaRes.text.replace(/```json|```/g, '')).status; } catch(e){}
      setFerpaStatus(status);

      if (status === 'passthrough') {
        const sampleRes = await callAIWithVS(
          "Select 3 variants from matched trajectories and label them 'most common', 'mid-frequency', 'rare but possible'. Output JSON.",
          `Matched: ${matchedIds.join(', ')}.`,
          { fallbackText: `{"selected_arcs": [{"id": "${matchedIds[0] || 'TRJ-0114'}", "probability_label": "most common path"}, {"id": "${matchedIds[1] || 'TRJ-0156'}", "probability_label": "mid-frequency path"}, {"id": "${matchedIds[2] || 'TRJ-0241'}", "probability_label": "rare but possible"}]}` }
        );
        try {
          const parsed = JSON.parse(sampleRes.text.replace(/```json|```/g, ''));
          const fullArcs = parsed.selected_arcs.map(sa => {
            const full = TRAJECTORIES.find(t => t.trajectory_id === sa.id) || TRAJECTORIES[0];
            return { ...full, probability_label: sa.probability_label };
          });
          setArcs(fullArcs);
        } catch(e) {
          setArcs(TRAJECTORIES.slice(0,3).map((t,i) => ({...t, probability_label: ['most common', 'mid-frequency', 'rare'][i]})));
        }
      }
      setIsLoading(false);
    };
    fetchResults();
  }, [query]);

  if (isLoading) {
    return (
      <div className="p-6 space-y-6">
        <Skeleton className="h-8 w-1/3" />
        <div className="space-y-4">
          {[1,2,3].map(i => <Skeleton key={i} className="h-24 w-full" />)}
        </div>
      </div>
    );
  }

  if (ferpaStatus === 'aggregate_only') {
    return (
      <div className="p-6 flex flex-col items-center justify-center h-full text-center space-y-4">
        <div className="w-48 h-48 rounded-full bg-surface flex items-center justify-center relative overflow-hidden">
           <div className="absolute inset-0 bg-gradient-to-br from-slate-200 to-slate-100 opacity-50 blur-xl" />
           <lucide.Users size={48} className="text-text-tertiary relative z-10" />
        </div>
        <h2 className="font-display text-[24px] font-bold">Privacy Guard Active</h2>
        <p className="font-body text-text-secondary max-w-md">
          Only 2 Trailblazers match this exact path — to protect their privacy, we'll show you the broader pattern instead.
        </p>
        <Button onClick={() => onNavigate('screen_search')} variant="secondary">Try a broader search</Button>
      </div>
    );
  }

  return (
    <div className="p-6 flex flex-col h-full">
      <div className="mb-6 flex justify-between items-end">
        <div>
          <p className="font-label text-text-tertiary uppercase tracking-wider mb-1">Results for</p>
          <h2 className="font-display text-[24px] font-bold text-text-primary">"{query}"</h2>
        </div>
      </div>

      <div className="space-y-4 flex-1 overflow-y-auto pr-2">
        {arcs.map((arc, idx) => (
          <motion.div
            key={arc.trajectory_id}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: idx * 0.12, duration: 0.4 }}
            className="group relative bg-white border border-border rounded-[4px] p-4 hover:border-nu-red hover:shadow-sm transition-all cursor-pointer"
            onClick={() => { setSelectedArcId(arc.trajectory_id); onNavigate('screen_arc_detail'); }}
          >
            <div className="flex justify-between items-start mb-4">
              <div>
                <h3 className="font-body font-semibold text-[16px] text-text-primary">{arc.end_role}</h3>
                <p className="font-data text-[13px] text-text-tertiary">{arc.end_industry} • Class of {arc.grad_year}</p>
              </div>
              <div className="flex items-center gap-3">
                <Badge variant="probability">{arc.probability_label}</Badge>
                <button 
                  onClick={(e) => { e.stopPropagation(); onSaveArc(arc.trajectory_id); }}
                  className="text-text-tertiary hover:text-nu-red transition-colors p-1"
                  aria-label="Save to Co-op Compass"
                >
                  <lucide.BookmarkPlus size={18} />
                </button>
              </div>
            </div>

