          </div>

          {/* Copilot Side Pane */}
          {!isDirector && (
            <motion.div 
              className="w-[480px] bg-white border-l border-border shadow-[-10px_0_30px_rgba(0,0,0,0.05)] flex flex-col z-30 relative"
              initial={{ x: 480 }} animate={{ x: 0 }} transition={{ duration: 0.28, ease: "easeOut" }}
            >
              {/* Copilot Header */}
              <div className="h-14 border-b border-border flex items-center px-4 justify-between bg-gradient-to-r from-white to-[#F3F2F1]">
                <div className="flex items-center gap-2">
                  <div className="w-6 h-6 rounded-[4px] bg-gradient-to-br from-[#5B5FC7] to-[#E3B5E3] flex items-center justify-center">
                    <lucide.Sparkles size={14} className="text-white" />
