                  <lucide.X size={20} className="cursor-pointer hover:text-text-primary" />
                </div>
              </div>

              {/* Screen Content */}
              <div className="flex-1 overflow-hidden relative">
                <AnimatePresence mode="wait">
                  <motion.div 
                    key={currentScreen}
                    initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }}
                    className="h-full"
                  >
                    {renderScreen()}
                  </motion.div>
                </AnimatePresence>
              </div>
            </motion.div>
          )}
        </div>

        {/* Global Toast */}
        <AnimatePresence>
          {toast && (
            <motion.div 
              initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }}
              className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-text-primary text-white px-4 py-3 rounded-[4px] shadow-lg font-body text-[14px] flex items-center gap-3 z-50"
            >
              <lucide.CheckCircle size={18} className="text-success" />
              {toast}
              <button className="ml-4 text-text-tertiary hover:text-white underline">view in Canvas</button>
            </motion.div>
          )}
        </AnimatePresence>

      </div>
    </div>
  );
};

// Verification block
function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

