          <Button variant="ghost" onClick={() => onNavigate('screen_fork_drilldown')}>Cancel</Button>
          <Button variant="teams" onClick={handleSend} loading={isSending} disabled={sent || isDrafting}>
            {sent ? <><lucide.Check size={16}/> Sent</> : "Send via Teams"}
          </Button>
        </div>
      </motion.div>
    </div>
  );
};

