// --- ROOT APP ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('screen_search');
  const [query, setQuery] = useState('');
  const [selectedArcId, setSelectedArcId] = useState(null);
  const [selectedForkId, setSelectedForkId] = useState(null);
  const [toast, setToast] = useState(null);

  const [clrLedger, setClrLedger] = useState(() => {
    try { return JSON.parse(sessionStorage.getItem('clr_ledger')) || []; } catch(e) { return []; }
  });
  const [savedArcs, setSavedArcs] = useState(() => {
    try { return JSON.parse(sessionStorage.getItem('saved_arcs')) || []; } catch(e) { return []; }
  });

  const logClrEvent = (eventType, trajectoryId, tag) => {
    const newEvent = { event_id: `CLR-${Date.now()}`, timestamp: new Date().toISOString(), event_type: eventType, trajectory_id: trajectoryId, clr_competency_tag: tag };
    const updated = [...clrLedger, newEvent];
    setClrLedger(updated);
    sessionStorage.setItem('clr_ledger', JSON.stringify(updated));
  };

  const handleSaveArc = (id) => {
    if (!savedArcs.includes(id)) {
      const updated = [...savedArcs, id];
      setSavedArcs(updated);
      sessionStorage.setItem('saved_arcs', JSON.stringify(updated));
      logClrEvent('arc_saved', id, 'career_exploration');
    }
    setToast("Saved to your Co-op Compass — revisit anytime.");
    setTimeout(() => setToast(null), 3000);
  };

  // Inject CSS Variables
  useEffect(() => {
    const style = document.createElement('style');
    style.innerHTML = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:wght@400;600;700&family=Roboto+Condensed:wght@400;700&display=swap');
      :root {
        --bg: #FFFFFF;
        --surface: #F7F7F7;
        --panel: #F0F0F0;
        --text-primary: #000000;
        --text-secondary: #414141;
        --text-tertiary: #737373;
        --border: #D9D9D9;
        --nu-red: #C8102E;
        --nu-red-deep: #9E0A24;
        --nu-red-tint: #FBE7EA;
        --success: #0F8A4B;
      }
      body { background-color: #EBEBEB; margin: 0; font-family: 'Open Sans', sans-serif; }
      .font-display { font-family: 'Roboto Condensed', sans-serif; letter-spacing: -0.01em; }
      .font-body { font-family: 'Open Sans', sans-serif; }
      .font-label { font-family: 'Open Sans', sans-serif; font-weight: 600; }
      .font-data { font-family: 'IBM Plex Mono', monospace; }

      @keyframes shimmer {
        100% { transform: translateX(100%); }
      }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const renderScreen = () => {
    switch (currentScreen) {
      case 'screen_search': return <ScreenSearch onNavigate={setCurrentScreen} setQuery={setQuery} query={query} savedCount={savedArcs.length} />;
      case 'screen_results': return <ScreenResults query={query} onNavigate={setCurrentScreen} setSelectedArcId={(id) => { setSelectedArcId(id); logClrEvent('arc_viewed', id, 'career_exploration'); }} onSaveArc={handleSaveArc} />;
      case 'screen_arc_detail': return <ScreenArcDetail arcId={selectedArcId} onNavigate={setCurrentScreen} setSelectedForkId={(forkId) => { setSelectedForkId(forkId); logClrEvent('fork_drilled', selectedArcId, 'decision_analysis'); }} />;
      case 'screen_fork_drilldown': return <ScreenForkDrilldown forkId={selectedForkId} onNavigate={setCurrentScreen} logClrEvent={logClrEvent} arcId={selectedArcId} />;
      case 'screen_counterfactual': return <ScreenCounterfactual forkId={selectedForkId} onNavigate={setCurrentScreen} logClrEvent={logClrEvent} arcId={selectedArcId} />;
      case 'screen_invite': return <ScreenInvite forkId={selectedForkId} onNavigate={setCurrentScreen} logClrEvent={logClrEvent} arcId={selectedArcId} />;
      case 'screen_director_dashboard': return <ScreenDirectorDashboard />;
      default: return <div>Screen not found</div>;
    }
  };

  const isDirector = currentScreen === 'screen_director_dashboard';

  return (
    <div className="w-screen h-screen flex items-center justify-center overflow-hidden relative">
      {/* Demo Controls */}
      <div className="fixed top-4 right-4 z-50 bg-white border border-border rounded-[4px] shadow-lg p-2 flex items-center gap-2">
        <span className="font-data text-[11px] text-text-tertiary">DEMO JUMP:</span>
        <select 
          className="font-body text-[13px] border border-border rounded-[2px] p-1 outline-none"
          value={currentScreen} 
          onChange={(e) => setCurrentScreen(e.target.value)}
        >
          <option value="screen_search">1. Search</option>
          <option value="screen_results">2. Results</option>
          <option value="screen_arc_detail">3. Arc Detail</option>
          <option value="screen_fork_drilldown">4. Fork Drilldown</option>
          <option value="screen_counterfactual">5. Counterfactual</option>
          <option value="screen_invite">6. Invite</option>
          <option value="screen_director_dashboard">7. Director Dashboard</option>
        </select>
      </div>

      {/* Main App Container (Simulating Teams Desktop Client) */}
      <div className="w-full max-w-[1440px] h-full max-h-[900px] bg-[#EBEBEB] flex shadow-2xl overflow-hidden relative">

        {/* Fake Teams Sidebar */}
        <div className="w-[68px] bg-white border-r border-border flex flex-col items-center py-4 gap-6 z-20">
          <div className="w-8 h-8 bg-[#5B5FC7] rounded-[4px] flex items-center justify-center text-white font-bold text-[14px]">T</div>
          <lucide.Bell size={24} className="text-text-tertiary" />
          <lucide.MessageSquare size={24} className="text-text-tertiary" />
          <lucide.Users size={24} className="text-text-tertiary" />
          <div className="mt-auto w-8 h-8 rounded-full bg-slate-300 flex items-center justify-center text-white font-bold text-[12px]">AO</div>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 flex relative">
          {/* Fake Teams Chat/Content Area */}
          <div className={`flex-1 bg-white transition-all duration-300 ${!isDirector ? 'opacity-50 blur-[2px]' : ''}`}>
            {isDirector ? (
              renderScreen()
            ) : (
              <div className="p-8">
                <div className="w-1/3 h-8 bg-surface rounded-[4px] mb-8" />
                <div className="space-y-4">
                  <div className="w-2/3 h-24 bg-surface rounded-[8px]" />
                  <div className="w-1/2 h-24 bg-surface rounded-[8px]" />
                </div>
              </div>
            )}
          </div>

          {/* Copilot Side Pane */}
          {!isDirector && (
            <motion.div 
              className="w-[480px] bg-white border-l border-border shadow-[-10px_0_30px_rgba(0,0,0,0.05)] flex flex-col z-30 relative"
              initial={{ x: 480 }} animate={{ x: 0 }} transition={{ duration: 0.28, ease: "easeOut" }}
            >
              {/* Copilot Header */}
              <div className="h-14 border-b border-border flex items-center px-4 justify-between bg-gradient-to-r from-white to-[#F3F2F1]">
                <div className="flex items-center gap-2">
                  <div className="w-6 h-6 rounded-[4px] bg-gradient-to-br from-[#5B5FC7] to-[#E3B5E3] flex items-center justify-center">
                    <lucide.Sparkles size={14} className="text-white" />
                  </div>
                  <span className="font-body font-semibold text-[14px] text-text-primary">Copilot</span>
                </div>
                <div className="flex items-center gap-3 text-text-tertiary">
                  <lucide.RotateCcw size={16} className="cursor-pointer hover:text-text-primary" onClick={() => setCurrentScreen('screen_search')} />
                  <lucide.X size={20} className="cursor-pointer hover:text-text-primary" />
                </div>
              </div>

              {/* Screen Content */}
              <div className="flex-1 overflow-hidden relative">
                <AnimatePresence mode="wait">
                  <motion.div 
                    key={currentScreen}
                    initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -10 }} transition={{ duration: 0.2 }}
                    className="h-full"
                  >
                    {renderScreen()}
                  </motion.div>
                </AnimatePresence>
              </div>
            </motion.div>
          )}
        </div>

        {/* Global Toast */}
        <AnimatePresence>
          {toast && (
            <motion.div 
              initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: 20 }}
              className="absolute bottom-8 left-1/2 -translate-x-1/2 bg-text-primary text-white px-4 py-3 rounded-[4px] shadow-lg font-body text-[14px] flex items-center gap-3 z-50"
            >
              <lucide.CheckCircle size={18} className="text-success" />
              {toast}
              <button className="ml-4 text-text-tertiary hover:text-white underline">view in Canvas</button>
            </motion.div>
          )}
        </AnimatePresence>

      </div>
    </div>
  );
};

// Verification block
function __test_state_transitions__() {
  console.assert(typeof App === 'function', 'App must be a component');
  return true;
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}

export default App;
